CREATE TABLE "workflow_executions" ("id" UUID NOT NULL,"workflow_type" VARCHAR(80) NOT NULL,"trigger" VARCHAR(80) NOT NULL,"entity_type" VARCHAR(60) NOT NULL,"entity_id" VARCHAR(80) NOT NULL,"status" VARCHAR(20) NOT NULL,"started_at" TIMESTAMP(3) NOT NULL,"completed_at" TIMESTAMP(3),"error" VARCHAR(2000),CONSTRAINT "workflow_executions_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "workflow_executions_trigger_entity_type_entity_id_key" ON "workflow_executions"("trigger","entity_type","entity_id");CREATE INDEX "workflow_executions_started_at_idx" ON "workflow_executions"("started_at");CREATE INDEX "workflow_executions_status_idx" ON "workflow_executions"("status");
